SC_PATCH_SHA = 'ee250ec858480dfa'
CHT_PATCH_SHA = 'c49f5363eda1787a'
FAMILY = 'DC4TC'
GLYPH_SCALE = 1.0          # installer v2.0 used 1.05: bigger glyphs in the same advance = smaller gaps
EXE = 'DC4_SH.exe'
STORE = 'DC4SH_CHT'
BASE_SIZE = 26             # the game's own message font size (Config.tjs defaultFontSize)


def scale_for(size):
    return round(size * 1000 / BASE_SIZE)


def size_keys(size):
    return [('EnableFontHeightScale', '1'), ('FontHeightScale1000', str(scale_for(size)))]


def size_inis():
    cands = ('FontHook.ini', os.path.join(STORE, 'CHT', 'FontHook.ini'), os.path.join(STORE, 'SC_backup', 'FontHook.ini'))
    return [p for p in cands if os.path.exists(p)]


def current_size():
    lines = ini_read('FontHook.ini')[1]
    v = ini_get(lines, 'FontHeightScale1000')
    if ini_get(lines, 'EnableFontHeightScale') != '1' or not (v and v.isdigit()):
        return None
    return round(int(v) * BASE_SIZE / 1000)


def set_size(size):
    """Change the text size only. FontHook reads it every time the game starts."""
    for p in size_inis():
        ini_update(p, tail=size_keys(size))
    return size_inis()


def is_installed():
    need = [os.path.join(STORE, 'CHT', n) for n in ('patch.xp3', 'GameFont.ttf', 'FontHook.ini')]
    return all(os.path.exists(p) for p in need) and os.path.exists(os.path.join(STORE, 'install.json'))


def install(size, version):
    if not os.path.exists(EXE):
        raise RuntimeError('This is not a D.C.4 Sweet Harmony folder (DC4_SH.exe missing).')
    store = STORE; scb = os.path.join(store, 'SC_backup'); cht = os.path.join(store, 'CHT')
    # 1. Simplified patch source
    if os.path.exists(os.path.join(scb, 'patch.xp3')):
        say('[1/5] Using saved Simplified patch backup')
    else:
        say('[1/5] Checking the Simplified Chinese patch...')
        for p in ('patch.xp3', 'FontHook.ini', 'winmm.dll'):
            if not os.path.exists(p):
                raise RuntimeError('The Simplified Chinese patch by acies was not found (%s is missing).\n'
                                   'Install it first (see README), then run this again.' % p)
        d = rd('patch.xp3')
        names = {e['name']: e.get('adler') for e in entries(d) if e['tag'] == b'File'}
        known = sum(1 for n, h in names.items() if n in KEYS and KEYS[n][0] == h)
        if known < len(KEYS) * 0.9:
            raise RuntimeError('patch.xp3 is not the expected Simplified patch (%d/%d files recognised).\n'
                               'If CHT was installed by hand, reinstall the Simplified patch first.' % (known, len(KEYS)))
        say('      backing up Simplified files -> %s' % scb)
        for p in ('patch.xp3', 'FontHook.ini', 'GameFont.otf', 'GameFont.ttf'):
            if os.path.exists(p): wr(os.path.join(scb, p), rd(p))
    src = rd(os.path.join(scb, 'patch.xp3'))
    if sha16(src) != SC_PATCH_SHA:
        say('      note: patch.xp3 differs from the tested release - converting what matches')
    ref_font = next((os.path.join(scb, n) for n in ('GameFont.otf', 'GameFont.ttf') if os.path.exists(os.path.join(scb, n))), None)
    if not ref_font: raise RuntimeError('GameFont.otf from the Simplified patch is missing.')

    # 2. convert
    say('[2/5] Converting text to Traditional Chinese...')
    from opencc import OpenCC
    cc = OpenCC('s2tw')
    items, used = [], {}
    nconv = nstr = nskip = 0
    for e in entries(src):
        if e['tag'] != b'File': continue
        seg = e['segs'][0]
        raw_item = dict(name=e['name'], flags=e['flags'], adler=e['adler'],
                        raw_segment=src[seg[1]:seg[1] + seg[3]], osize=seg[2], seg_flag=seg[0])
        k = KEYS.get(e['name'])
        if not (e['name'].endswith('.scn') and k and k[0] == e['adler'] and len(e['segs']) == 1):
            if e['name'].endswith('.scn'): nskip += 1
            items.append(raw_item); continue
        enc = read_file(src, e)
        ks = keystream(k[1], len(enc))
        plain = bytes(a ^ b for a, b in zip(enc, ks))
        if plain[:4] != b'PSB\x00':
            nskip += 1; items.append(raw_item); continue
        p = PSB(plain)
        ch = plan(p, cc)
        new = apply(plain, p, ch)
        q = PSB(new)
        for i in range(len(q.str_offsets)):
            for c in q.string(i): used[c] = used.get(c, 0) + 1
        if not ch:
            items.append(raw_item); continue
        items.append(dict(name=e['name'], flags=e['flags'], adler=e['adler'], data=bytes(a ^ b for a, b in zip(new, ks))))
        nconv += 1; nstr += len(ch)
    os.makedirs(cht, exist_ok=True)
    out_xp3 = os.path.join(cht, 'patch.xp3')
    write_xp3(out_xp3, items)
    same = sha16(rd(out_xp3)) == CHT_PATCH_SHA
    say('      %d scripts, %d text strings converted%s%s' % (nconv, nstr, ' (identical to the reference build)' if same else '',
                                                           '' if not nskip else '; %d unrecognised scripts left as-is' % nskip))

    # 3. font
    say('[3/5] Building font from Microsoft JhengHei Bold...')
    base = find_font('msjhbd.ttc', 'msjh.ttc')
    if not base: raise RuntimeError('Microsoft JhengHei (msjhbd.ttc / msjh.ttc) not found in Windows Fonts.')
    fb = find_font('YuGothB.ttc', 'YuGothM.ttc', 'YuGothR.ttc', 'msgothic.ttc', 'seguisym.ttf')
    say('      source: %s' % base)
    build_font_sh(base, fb, ref_font, used, os.path.join(cht, 'GameFont.ttf'), FAMILY, GLYPH_SCALE,
                  log=lambda m: say('   ' + m.strip()))
    bom, ini = ini_read(os.path.join(scb, 'FontHook.ini'))
    ini_write(os.path.join(cht, 'FontHook.ini'),
              ini_set(ini, head=[('FontNameW', FAMILY), ('FontNameA', FAMILY)], tail=size_keys(size)), bom)
    ini_update(os.path.join(scb, 'FontHook.ini'), tail=size_keys(size))     # Simplified keeps the same size

    # 4. switch scripts
    say('[4/5] Writing the switch scripts...')
    def bat(name, srcdir, font, msg):
        lines = ['@echo off', 'cd /d "%~dp0"',
                 'if not exist "%s\\patch.xp3" (echo [ERROR] %s not found. & pause & exit /b 1)' % (srcdir, srcdir),
                 'echo Close the game first.',
                 'copy /y "%s\\patch.xp3" "patch.xp3" >nul' % srcdir,
                 'if errorlevel 1 (echo [ERROR] copy failed - is the game still running? & pause & exit /b 1)',
                 'del /q "GameFont.otf" "GameFont.ttf" 2>nul',
                 'copy /y "%s\\%s" "%s" >nul' % (srcdir, font, font),
                 'copy /y "%s\\FontHook.ini" "FontHook.ini" >nul' % srcdir,
                 'echo Done. %s' % msg, 'pause']
        wr(name, ('\r\n'.join(lines) + '\r\n').encode('ascii'))
    sc_font = os.path.basename(ref_font)
    bat('切換繁體中文(CHT).bat', cht, 'GameFont.ttf', 'Traditional Chinese (CHT)')
    bat('切换简体中文(CHS).bat', scb, sc_font, 'Simplified Chinese (original patch)')

    # 5. apply
    say('[5/5] Installing Traditional Chinese...')
    wr('patch.xp3', rd(out_xp3))
    for n in ('GameFont.otf', 'GameFont.ttf'):
        if os.path.exists(n): os.remove(n)
    wr('GameFont.ttf', rd(os.path.join(cht, 'GameFont.ttf')))
    wr('FontHook.ini', rd(os.path.join(cht, 'FontHook.ini')))
    wr(os.path.join(store, 'install.json'),
       json.dumps({'tool': 'DC4-CHT-Patch', 'version': version, 'size': size}).encode('utf-8'))
